-- Run once, on first start of an empty data volume.
--
-- Extensions only: every table lives in a versioned migration owned by the API
-- (specs/05-backend-and-jobs.md §5), so that local, staging and production
-- schemas come from one source.

-- Vector search for the Universe and semantic song search (01 §1, 08 §6).
CREATE EXTENSION IF NOT EXISTS vector;

-- gen_random_uuid() and digest(); ULIDs are generated by the application.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
